$target = Join-Path $PSScriptRoot '..\server\src\quran-admin.js'
$source = Get-Content -LiteralPath $target -Raw
$old = "router.get('/api/admin/quran/surahs',admin,async(_req,res)=>{try{const rows=await getSurahs().find({},{projection:{_id:0,number:1,name:1,englishName:1,englishNameTranslation:1,numberOfAyahs:1,revelationType:1,localizedNames:1,'ayahs.translations':1}}).sort({number:1}).toArray();const data=rows.map(row=>{const progress={};for(const ayah of row.ayahs||[])for(const [code,text] of Object.entries(ayah.translations||{}))if(code!=='en'&&String(text||'').trim())progress[code]=(progress[code]||0)+1;const{ayahs,...summary}=row;return{...summary,translationProgress:progress}});res.json({data})}catch(error){console.error(error);res.status(500).json({message:'Unable to load Quran content.'})}});"
$new = "router.get('/api/admin/quran/surahs',admin,async(_req,res)=>{try{const collection=getSurahs(),rows=await collection.find({},{projection:{_id:0,number:1,name:1,englishName:1,englishNameTranslation:1,numberOfAyahs:1,revelationType:1,localizedNames:1}}).sort({number:1}).toArray(),stats=await collection.aggregate([{`$unwind:'`$ayahs'},{`$project:{number:1,pairs:{`$objectToArray:{`$ifNull:['`$ayahs.translations',{}]}}}},{`$unwind:'`$pairs'},{`$match:{'pairs.k':{`$ne:'en'},'pairs.v':{`$type:'string',`$ne:''}}},{`$group:{_id:{number:'`$number',code:'`$pairs.k'},count:{`$sum:1}}},{`$group:{_id:'`$_id.number',entries:{`$push:{k:'`$_id.code',v:'`$count'}}}},{`$project:{_id:0,number:'`$_id',progress:{`$arrayToObject:'`$entries'}}}]).toArray(),byNumber=new Map(stats.map(item=>[item.number,item.progress]));res.json({data:rows.map(row=>({...row,translationProgress:byNumber.get(row.number)||{}}))})}catch(error){console.error(error);res.status(500).json({message:'Unable to load Quran content.'})}});"
if (-not $source.Contains($old)) { throw 'Old Quran summary route not found' }
$source = $source.Replace($old,$new)
Set-Content -LiteralPath $target -Value $source -NoNewline -Encoding utf8
